-- Knowledge base by IT assistant domain: one category per business system
-- (OPERA PMS, Sage 1000, Citrix), the two Opera articles moved there, and
-- articles for the domains that had none or few (Sage 1000, Citrix, OPERA
-- PMS, tills, network, Microsoft 365, maintenance), in French and English.
-- Guidance stays first-line and safe: anything that changes a business
-- system is left to its authorised administrator.
begin;

update public.kb_articles set category = 'OPERA PMS'
where category = 'Logiciels' and title like 'Opera :%';

insert into public.kb_articles (title, title_en, category, published, created_by, updated_by, body, body_en)
select v.title, v.title_en, v.category, true, null, null, v.body, v.body_en
from (values
  -- OPERA PMS
  ('Opera est lent ou figé', 'Opera is slow or frozen', 'OPERA PMS',
   E'1. Attendez une minute : une recherche ou un rapport lourd peut prendre du temps.\n2. Vérifiez si vos collègues ont le même problème : si oui, ne relancez rien et créez un ticket Urgent.\n3. Si vous êtes seul touché, enregistrez ce qui peut l''être, fermez Opera puis rouvrez-le.\n4. Redémarrez le poste si Opera ne répond plus du tout.\nNe forcez jamais la fermeture pendant un encaissement ou un check-out.',
   E'1. Wait one minute: a heavy search or report can take time.\n2. Check whether colleagues have the same problem: if so, do not restart anything and create an Urgent ticket.\n3. If only you are affected, save what you can, close Opera, then open it again.\n4. Restart the computer if Opera does not respond at all.\nNever force-close during a payment or a check-out.'),
  ('Opera : la clôture de nuit (Night Audit) est bloquée', 'Opera: the Night Audit is stuck', 'OPERA PMS',
   E'1. Ne relancez pas la clôture et ne fermez pas Opera sur le poste qui la fait tourner.\n2. Notez l''étape affichée et le message d''erreur exact, avec l''heure.\n3. Vérifiez qu''aucun autre poste n''a une note client ou une caisse ouverte, si la procédure de l''hôtel le demande.\n4. Créez un ticket Urgent (catégorie IT / Réseau) : seul l''administrateur Opera ou le support éditeur reprend une clôture interrompue.',
   E'1. Do not restart the audit and do not close Opera on the computer running it.\n2. Write down the step shown and the exact error message, with the time.\n3. Check that no other computer has a guest folio or a till open, if the hotel''s procedure requires it.\n4. Create an Urgent ticket (IT / Network category): only the Opera administrator or the vendor support resumes an interrupted audit.'),
  ('Opera : la carte de chambre ne s''encode pas depuis Opera', 'Opera: the key card does not encode from Opera', 'OPERA PMS',
   E'1. Vérifiez que la carte est bien posée sur l''encodeur et que l''encodeur est allumé.\n2. Réessayez une fois depuis la réservation dans Opera.\n3. Si cela ne marche toujours pas, encodez la carte directement sur le logiciel des serrures (procédure de secours de la réception).\n4. Créez un ticket : l''interface entre Opera et les serrures est peut-être arrêtée. Indiquez le numéro de chambre et l''heure.',
   E'1. Check that the card sits on the encoder and that the encoder is on.\n2. Try once more from the reservation in Opera.\n3. If it still fails, encode the card directly in the lock software (reception fallback procedure).\n4. Create a ticket: the interface between Opera and the locks may be down. Give the room number and the time.'),
  ('Opera : envoyer une facture par e-mail au client', 'Opera: e-mail an invoice to the guest', 'OPERA PMS',
   E'1. Vérifiez l''adresse e-mail du client dans son profil.\n2. Depuis la note (folio), choisissez l''envoi par e-mail ; si l''option n''existe pas, enregistrez la facture en PDF et envoyez-la depuis la boîte e-mail de la réception.\n3. Le client ne la reçoit pas : demandez-lui de regarder ses courriers indésirables.\n4. Si l''envoi échoue avec un message d''erreur, créez un ticket avec le message exact.',
   E'1. Check the guest''s e-mail address in the profile.\n2. From the folio, choose e-mail sending; if the option does not exist, save the invoice as PDF and send it from the reception mailbox.\n3. The guest does not receive it: ask them to check their junk mail.\n4. If sending fails with an error message, create a ticket with the exact message.'),
  ('Opera : demander un accès ou un nouveau rôle', 'Opera: request access or a new role', 'OPERA PMS',
   E'1. Créez un ticket (catégorie Accès) en indiquant : nom, hôtel, service, rôle demandé (réception, réservations, comptabilité…) et date de début.\n2. Ajoutez l''accord de votre responsable.\n3. L''administrateur Opera crée le compte avec le minimum de droits utiles et vous transmet l''accès par un canal sûr.\nNe partagez jamais un compte Opera entre collègues : chaque action est tracée à votre nom.',
   E'1. Create a ticket (Access category) with: name, hotel, department, requested role (front desk, reservations, accounting…) and start date.\n2. Add your manager''s approval.\n3. The Opera administrator creates the account with the minimum rights needed and sends the access through a safe channel.\nNever share an Opera account between colleagues: every action is logged in your name.'),
  -- Sage 1000
  ('Sage 1000 ne s''ouvre pas ou refuse la connexion', 'Sage 1000 does not open or refuses sign-in', 'Sage 1000',
   E'1. Vérifiez que vous êtes sur le réseau de l''hôtel ou connecté au VPN / à Citrix si Sage s''ouvre par là.\n2. Vérifiez l''identifiant et la touche Verr. Maj.\n3. Notez le message exact : « licence », « base indisponible » ou « mot de passe » n''ont pas la même cause.\n4. Créez un ticket avec ce message. Ne réessayez pas plusieurs fois un mot de passe : le compte peut se bloquer.',
   E'1. Check that you are on the hotel network, or connected to the VPN / Citrix if Sage opens through it.\n2. Check the login and Caps Lock.\n3. Write down the exact message: "licence", "database unavailable" or "password" have different causes.\n4. Create a ticket with that message. Do not retry a password many times: the account may lock.'),
  ('Sage 1000 lent ou bloqué pendant un traitement', 'Sage 1000 slow or stuck during a process', 'Sage 1000',
   E'1. Si un traitement est en cours (saisie de lot, édition, clôture, export), attendez : ne fermez pas Sage et n''éteignez pas le poste.\n2. Demandez à vos collègues comptables si Sage est lent pour eux aussi.\n3. Notez l''opération en cours, l''heure de début et le message éventuel.\n4. Créez un ticket : l''IT vérifie avec le responsable financier avant toute action. Ne relancez jamais un traitement de clôture vous-même.',
   E'1. If a process is running (batch entry, report, closing, export), wait: do not close Sage and do not turn off the computer.\n2. Ask your accounting colleagues whether Sage is slow for them too.\n3. Write down the operation, its start time and any message.\n4. Create a ticket: IT checks with the finance manager before any action. Never restart a closing process yourself.'),
  ('Sage 1000 : imprimer ou exporter un état', 'Sage 1000: print or export a report', 'Sage 1000',
   E'1. Vérifiez l''imprimante choisie dans la fenêtre d''impression de Sage (dans Citrix, l''imprimante peut porter un nom différent).\n2. Essayez l''aperçu puis l''export en PDF ou Excel, et imprimez le fichier depuis Windows.\n3. L''état est vide : vérifiez la période et les filtres choisis.\n4. Toujours bloqué : créez un ticket avec le nom de l''état et une capture du message.',
   E'1. Check the printer chosen in Sage''s print window (in Citrix, the printer may have a different name).\n2. Try the preview, then export to PDF or Excel, and print the file from Windows.\n3. The report is empty: check the period and filters chosen.\n4. Still stuck: create a ticket with the report name and a screenshot of the message.'),
  ('Sage 1000 : préparer une clôture de mois', 'Sage 1000: prepare a month-end closing', 'Sage 1000',
   E'1. Prévenez l''IT la veille d''une clôture : aucune mise à jour ni redémarrage de serveur ne sera prévu ce jour-là.\n2. Vérifiez avec le responsable financier qu''une sauvegarde récente existe.\n3. Lancez la clôture depuis un seul poste, sans autre utilisateur connecté si la procédure l''exige.\n4. En cas d''erreur, ne relancez pas : notez le message et créez un ticket Urgent.',
   E'1. Tell IT the day before a closing: no update or server restart will be planned that day.\n2. Check with the finance manager that a recent backup exists.\n3. Run the closing from a single computer, with no other user connected if the procedure requires it.\n4. If an error appears, do not restart: write down the message and create an Urgent ticket.'),
  -- Citrix
  ('Citrix ne s''ouvre pas ou l''application n''apparaît pas', 'Citrix does not open or the application is missing', 'Citrix',
   E'1. Vérifiez votre connexion Internet en ouvrant un site web.\n2. Fermez complètement Citrix Workspace (icône près de l''horloge), puis rouvrez-le et reconnectez-vous.\n3. L''application (Sage, Opera…) n''apparaît pas dans la liste : votre accès n''est peut-être pas attribué, créez un ticket en indiquant l''application.\n4. Notez le message d''erreur exact si la connexion échoue.',
   E'1. Check your Internet connection by opening a website.\n2. Fully close Citrix Workspace (icon near the clock), then open it again and sign in.\n3. The application (Sage, Opera…) is not in the list: your access may not be assigned, create a ticket naming the application.\n4. Write down the exact error message if sign-in fails.'),
  ('Citrix se déconnecte ou la session est figée', 'Citrix disconnects or the session is frozen', 'Citrix',
   E'1. Patientez 30 secondes : la session se reconnecte souvent seule.\n2. Si elle reste figée, fermez uniquement la fenêtre Citrix sur votre poste et rouvrez l''application : votre session est en général retrouvée.\n3. Vérifiez votre connexion (Wi-Fi faible, câble débranché).\n4. Si cela se répète, créez un ticket avec les heures des coupures et l''application utilisée.',
   E'1. Wait 30 seconds: the session often reconnects by itself.\n2. If it stays frozen, close only the Citrix window on your computer and reopen the application: your session is usually found again.\n3. Check your connection (weak Wi-Fi, unplugged cable).\n4. If it keeps happening, create a ticket with the times of the cuts and the application used.'),
  ('Citrix : imprimer depuis une application', 'Citrix: print from an application', 'Citrix',
   E'1. Dans la fenêtre d''impression, choisissez l''imprimante de votre poste : dans Citrix, son nom est souvent suivi de « (depuis NOMDUPOSTE) » ou « redirected ».\n2. Vérifiez que cette imprimante fonctionne depuis Windows (page test).\n3. Fermez et rouvrez l''application Citrix pour que l''imprimante soit reconnue.\n4. Toujours bloqué : créez un ticket avec le nom de l''imprimante et de l''application.',
   E'1. In the print window, choose your computer''s printer: in Citrix its name is often followed by "(from COMPUTERNAME)" or "redirected".\n2. Check that this printer works from Windows (test page).\n3. Close and reopen the Citrix application so the printer is detected.\n4. Still stuck: create a ticket with the printer and application names.'),
  ('Citrix : copier un fichier entre mon poste et Citrix', 'Citrix: copy a file between my computer and Citrix', 'Citrix',
   E'1. Utilisez le dossier partagé indiqué par l''IT (ou OneDrive) plutôt que le bureau du poste.\n2. Si Citrix demande l''autorisation d''accéder à vos fichiers, acceptez seulement pour l''application de travail.\n3. Le copier-coller ne marche pas : réessayez après avoir fermé et rouvert l''application.\nNe stockez pas de données de clients sur une clé USB pour les transférer.',
   E'1. Use the shared folder given by IT (or OneDrive) rather than the computer''s desktop.\n2. If Citrix asks for permission to access your files, allow it only for the work application.\n3. Copy and paste does not work: try again after closing and reopening the application.\nDo not store guest data on a USB stick to move it.'),
  -- Caisse / POS
  ('Le paiement par carte (TPE) est refusé ou hors ligne', 'Card payment (terminal) declined or offline', 'Caisse',
   E'1. Refusé par la banque : proposez un autre moyen de paiement, l''IT ne peut rien changer à un refus.\n2. TPE « hors ligne » : vérifiez son câble réseau ou sa base, puis redémarrez-le.\n3. Si plusieurs TPE sont hors ligne, créez un ticket Urgent.\n4. N''encaissez jamais deux fois sans vérifier le ticket de la première tentative.\nNe notez jamais un numéro de carte, ni sur papier ni dans un ticket.',
   E'1. Declined by the bank: offer another payment method, IT cannot change a decline.\n2. Terminal "offline": check its network cable or base, then restart it.\n3. If several terminals are offline, create an Urgent ticket.\n4. Never charge twice without checking the receipt of the first attempt.\nNever write down a card number, on paper or in a ticket.'),
  ('Caisse : un article ou un prix manque sur la caisse', 'Till: an item or price is missing', 'Caisse',
   E'1. Vérifiez que vous êtes sur le bon point de vente (bar, restaurant, room service).\n2. Utilisez l''article « divers » prévu par le F&B en attendant, si votre procédure l''autorise.\n3. Demandez la création ou la correction au responsable F&B, puis créez un ticket avec le nom, le prix et le point de vente : la modification des menus est faite par l''administrateur caisse.',
   E'1. Check that you are on the right outlet (bar, restaurant, room service).\n2. Use the "miscellaneous" item planned by F&B meanwhile, if your procedure allows it.\n3. Ask the F&B manager for the creation or correction, then create a ticket with the name, price and outlet: menus are changed by the till administrator.'),
  ('La caisse est hors ligne ou ne se synchronise plus', 'The till is offline or no longer syncs', 'Caisse',
   E'1. Vérifiez le câble réseau de la caisse et le voyant de la prise.\n2. Continuez à encaisser si la caisse le permet en mode hors ligne : les ventes se synchronisent au retour du réseau.\n3. Redémarrez la caisse par le menu quand aucune commande n''est ouverte.\n4. Si plusieurs caisses sont touchées ou si les commandes n''arrivent plus en cuisine, créez un ticket Urgent.',
   E'1. Check the till''s network cable and the socket light.\n2. Keep taking payments if the till allows offline mode: sales sync when the network is back.\n3. Restart the till from the menu when no order is open.\n4. If several tills are affected or orders no longer reach the kitchen, create an Urgent ticket.'),
  -- IT / Réseau
  ('Internet est lent ou coupé dans tout l''hôtel', 'Internet is slow or down across the hotel', 'Réseau',
   E'1. Vérifiez sur plusieurs postes et un téléphone en Wi-Fi : est-ce tout l''hôtel ou une seule zone ?\n2. Ne redémarrez pas vous-même les équipements de la salle informatique.\n3. Créez un ticket Urgent en indiquant depuis quand, les zones touchées et si Opera, les caisses ou les cartes de chambre sont touchés.\n4. L''IT vérifie le pare-feu, la liaison Internet et contacte l''opérateur si besoin.',
   E'1. Check on several computers and a phone on Wi-Fi: is it the whole hotel or one area?\n2. Do not restart the server room equipment yourself.\n3. Create an Urgent ticket saying since when, the areas affected and whether Opera, tills or key cards are affected.\n4. IT checks the firewall and the Internet link, and calls the provider if needed.'),
  ('Une prise réseau ne fonctionne pas', 'A network socket does not work', 'Réseau',
   E'1. Essayez un autre câble et une autre prise si possible.\n2. Vérifiez que le câble est bien enfoncé des deux côtés (un clic doit se faire entendre).\n3. Notez le numéro inscrit sur la prise murale.\n4. Créez un ticket avec ce numéro et le lieu : l''IT vérifiera le brassage dans la baie.',
   E'1. Try another cable and another socket if possible.\n2. Check the cable is fully inserted at both ends (you should hear a click).\n3. Write down the number printed on the wall socket.\n4. Create a ticket with that number and the place: IT will check the patching in the rack.'),
  ('Un appareil (imprimante, caisse, TV) ne trouve plus le réseau', 'A device (printer, till, TV) no longer finds the network', 'Réseau',
   E'1. Éteignez l''appareil 30 secondes puis rallumez-le.\n2. Vérifiez son câble réseau ou, en Wi-Fi, le nom du réseau auquel il est connecté.\n3. Si d''autres appareils de la même zone sont touchés, signalez-le : c''est peut-être un switch.\n4. Créez un ticket avec le nom de l''appareil et son emplacement.',
   E'1. Turn the device off for 30 seconds, then on again.\n2. Check its network cable or, on Wi-Fi, the network name it is connected to.\n3. If other devices in the same area are affected, say so: it may be a switch.\n4. Create a ticket with the device name and its location.'),
  -- Microsoft 365
  ('Outlook : ouvrir une boîte partagée (réception, réservations…)', 'Outlook: open a shared mailbox (reception, reservations…)', 'Messagerie',
   E'1. Une boîte partagée apparaît en général seule dans Outlook quelques heures après l''attribution de l''accès.\n2. Elle n''apparaît pas : fermez et rouvrez Outlook, ou ouvrez-la sur https://outlook.office.com (votre photo > Ouvrir une autre boîte aux lettres).\n3. Vous n''avez pas l''accès : créez un ticket (catégorie Accès) avec le nom de la boîte et l''accord de votre responsable.',
   E'1. A shared mailbox usually appears in Outlook by itself a few hours after access is granted.\n2. It does not appear: close and reopen Outlook, or open it on https://outlook.office.com (your picture > Open another mailbox).\n3. You have no access: create a ticket (Access category) with the mailbox name and your manager''s approval.'),
  ('Partager un fichier en toute sécurité', 'Share a file safely', 'Messagerie',
   E'1. Partagez depuis OneDrive ou SharePoint plutôt qu''en pièce jointe : bouton « Partager », puis choisissez les personnes précises.\n2. Évitez les liens « Tout le monde avec le lien » pour les documents internes ou avec des données clients.\n3. Pour un partenaire extérieur, limitez la durée du lien si l''option existe.\n4. Une personne ne peut pas ouvrir le fichier : vérifiez qu''elle utilise l''adresse e-mail à laquelle vous l''avez partagé.',
   E'1. Share from OneDrive or SharePoint rather than as an attachment: "Share" button, then choose the exact people.\n2. Avoid "Anyone with the link" links for internal documents or guest data.\n3. For an outside partner, limit the link duration if the option exists.\n4. Someone cannot open the file: check they use the e-mail address you shared it with.'),
  ('Office indique « produit sans licence » ou demande de se connecter', 'Office says "unlicensed product" or asks to sign in', 'Messagerie',
   E'1. Cliquez sur « Se connecter » et utilisez votre adresse professionnelle.\n2. Fermez toutes les applications Office puis rouvrez Word ou Excel.\n3. Si le message continue, votre licence n''est peut-être pas attribuée : créez un ticket avec une capture du message.\nVous pouvez travailler en attendant sur https://www.office.com.',
   E'1. Click "Sign in" and use your work address.\n2. Close all Office applications, then reopen Word or Excel.\n3. If the message continues, your licence may not be assigned: create a ticket with a screenshot of the message.\nMeanwhile you can work on https://www.office.com.'),
  -- Maintenance
  ('Un onduleur émet des bips', 'A UPS is beeping', 'Matériel',
   E'1. Des bips réguliers signifient souvent que l''onduleur fonctionne sur batterie : vérifiez si le courant est coupé dans la zone.\n2. N''éteignez pas l''onduleur et ne débranchez rien : les serveurs et les caisses peuvent s''arrêter net.\n3. Notez le voyant ou le message affiché.\n4. Créez un ticket Urgent avec l''emplacement de l''onduleur.',
   E'1. Regular beeps often mean the UPS is running on battery: check whether power is cut in the area.\n2. Do not turn off the UPS and do not unplug anything: servers and tills may stop abruptly.\n3. Write down the light or message shown.\n4. Create an Urgent ticket with the UPS location.'),
  ('La salle informatique est trop chaude', 'The server room is too hot', 'Matériel',
   E'1. Vérifiez que la climatisation de la salle fonctionne et que la porte est fermée.\n2. Ne bloquez pas les grilles d''aération des baies avec des cartons ou du matériel.\n3. Prévenez la technique pour la climatisation et créez un ticket Urgent pour l''IT : la chaleur peut arrêter les serveurs.',
   E'1. Check that the room''s air conditioning works and that the door is closed.\n2. Do not block the racks'' vents with boxes or equipment.\n3. Tell the maintenance team about the air conditioning and create an Urgent ticket for IT: heat can stop the servers.'),
  ('Odeur de brûlé, fumée ou étincelle sur un appareil', 'Burning smell, smoke or spark from a device', 'Matériel',
   E'1. Votre sécurité d''abord : éloignez-vous de l''appareil.\n2. Si c''est possible sans risque, coupez son alimentation à l''interrupteur ou à la multiprise.\n3. En cas de fumée importante ou de flamme, appliquez la procédure incendie de l''hôtel.\n4. Ne rebranchez pas l''appareil et créez un ticket Urgent avec son emplacement.',
   E'1. Your safety first: move away from the device.\n2. If it is safe, cut its power at the switch or power strip.\n3. In case of heavy smoke or flames, follow the hotel''s fire procedure.\n4. Do not plug the device back in and create an Urgent ticket with its location.')
) as v(title, title_en, category, body, body_en)
where not exists (select 1 from public.kb_articles k where k.title = v.title);

commit;
